// hasIdentityReplayRule reports whether gf contains a present identity-bearing plane
// whose declared rule for source matches the given combination rule.
func (gf *generatedFrozen) hasIdentityReplayRule(source SourceKind, rule Combination) (string, bool) {
	if gf == nil {
		return "", false
	}
	if canonicalPlaneAttemptTransformsPolicy.rules.RuleFor(source) == rule {
		if len(gf.attemptTransforms) > 0 {
			return canonicalPlaneAttemptTransformsPolicy.planeID, true
		}
	}
	if canonicalPlaneStreamObserverFactoriesPolicy.rules.RuleFor(source) == rule {
		if len(gf.streamObserverFactories) > 0 {
			return canonicalPlaneStreamObserverFactoriesPolicy.planeID, true
		}
	}
	if canonicalPlaneCompactionPreserversPolicy.rules.RuleFor(source) == rule {
		if len(gf.compactionPreservers) > 0 {
			return canonicalPlaneCompactionPreserversPolicy.planeID, true
		}
	}
	if canonicalPlaneSecretGuardExecutionPolicy.rules.RuleFor(source) == rule {
		if !isNilValue(gf.secretGuardExecution) {
			return canonicalPlaneSecretGuardExecutionPolicy.planeID, true
		}
	}
	if canonicalPlaneTerminalDecisionProviderPolicy.rules.RuleFor(source) == rule {
		if !isNilValue(gf.terminalDecisionProvider) {
			return canonicalPlaneTerminalDecisionProviderPolicy.planeID, true
		}
	}
	if canonicalPlaneSessionClassifierPolicy.rules.RuleFor(source) == rule {
		if !isNilValue(gf.sessionClassifier) {
			return canonicalPlaneSessionClassifierPolicy.planeID, true
		}
	}
	if canonicalPlaneControlToolProviderPolicy.rules.RuleFor(source) == rule {
		if !isNilValue(gf.controlToolProvider) {
			return canonicalPlaneControlToolProviderPolicy.planeID, true
		}
	}
	return "", false
}

